sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  console.log('api data processing for filtered publisher');
  // var apiData = api.data.get_filter_publisher_1.output;
  var apiData = api.data.catalog_integration_publishers_1.output;
  // console.log('api data processing for filtered publisher',JSON.stringify(apiData));

  if (!apiData || !Array.isArray(apiData)) {
    return [];
  }

  // Transform the nested array structure into a flat array of objects with id and label
  var formattedData = apiData.flatMap(item => {
    if (Array.isArray(item) && item.length > 0) {
      // console.log('yes it is processing')
      return item.map(subItem => {
        return {
          id: subItem.id,
          label: subItem.label
        };
      });
    }
    return [];
  });
      // console.log('technical', formattedData);

  return formattedData;
}
